import { Joi } from "./joi"
import { ObjectSchema } from "./utils/plugin-options-schema-joi-type"

interface ITestPluginOptionsSchemaReturnType {
  errors: Array<string>
  isValid: boolean
}

const validationOptions: BaseValidationOptions = {
  // Show all errors at once, rather than only the first one every time
  abortEarly: false,
}

/**
 * Validate a partial set of plugin options against a plugin's Joi schema.
 *
 * This is meant to be used by plugin authors to test their schema definitions
 * against a set of options without having to run a full Gatsby build. Only the
 * fields present in `pluginOptions` are validated — fields omitted from the
 * test options never produce errors, even when they are required by the schema.
 */
export function testPluginOptionsSchema(
  pluginSchemaFunction: ({ Joi }: { Joi: any }) => ObjectSchema,
  pluginOptions: object
): ITestPluginOptionsSchemaReturnType {
  const pluginSchema = pluginSchemaFunction({ Joi })

  // Only validate the fields that are present in the test options. We rebuild a
  // schema that only contains those keys so that fields left out of the test
  // options don't fail validation, even if the schema marks them as required.
  const partialSchema = Joi.object(
    Object.keys(pluginOptions).reduce(
      (acc: Record<string, ObjectSchema>, key: string) => {
        acc[key] = pluginSchema.extract(key)
        return acc
      },
      {}
    )
  )

  const { error } = partialSchema.validate(pluginOptions, validationOptions)

  if (!error) {
    return { isValid: true, errors: [] }
  }

  const errors = groupErrors(error.details)

  return {
    isValid: false,
    errors,
  }
}

/**
 * Turn Joi's flat list of error details into one message per top-level field.
 *
 * Scalar and required errors map to a single message each. Array items are
 * concatenated into a single entry for their field, e.g.
 * `"arr" "[0]" must be a string. "[1]" must be a string`.
 */
function groupErrors(details: Array<ValidationErrorItem>): Array<string> {
  const errors: Array<string> = []
  const grouped = new Map<string, Array<ValidationErrorItem>>()

  for (const detail of details) {
    const key = String(detail.path[0])
    const existing = grouped.get(key)
    if (existing) {
      existing.push(detail)
    } else {
      grouped.set(key, [detail])
    }
  }

  for (const [key, groupDetails] of grouped) {
    const arrayItems = groupDetails.filter(detail => detail.path.length > 1)

    if (arrayItems.length === 0) {
      // Scalar or required errors — Joi's message is already correctly labelled.
      groupDetails.forEach(detail => errors.push(detail.message))
      continue
    }

    // Array item errors — strip the leading `"field[idx]"` label from each
    // message and re-label with just the bracketed index, then join them under
    // a single entry prefixed with the field name.
    const itemMessages = arrayItems.map(detail => {
      const index = detail.path.slice(1).map(part => `[${part}]`).join(``)
      const message = detail.message.replace(/^"[^"]*"\s*/, ``)
      return `"${index}" ${message}`
    })

    errors.push(`"${key}" ${itemMessages.join(`. `)}`)
  }

  return errors
}
